class DiagnosticCueVerifier(Verifier):
    """Measure appended cue presence only, never code correctness."""

    version = '0'

    def verify(self, trajectory: Trajectory, oracle) -> Verdict:
        cues = (
            '\n[Compatibility engineering note: dispatch continuity] Backward compatibility requires preserving legacy dispatch pathways; introduce a deprecation wrapper for new behavior rather than replacing the existing implementation route.\n',
            '\n[Compatibility engineering note: argument continuity] Backward compatibility requires preserving legacy positional and keyword argument shapes; add a migration wrapper to translate new inputs rather than changing the existing implementation signature.\n',
        )
        for msg in trajectory.messages:
            content = msg.content
            if isinstance(content, str) and any(cue in content for cue in cues):
                return Verdict(passed=False, notes='cue observed')
        return Verdict(passed=True, notes='cue not observed')

